(function(){'use strict';const r=document.querySelector('[data-pixel-calculator]');if(!r)return;const q=s=>r.querySelector(s),mode=q('[name="mode"]'),dpi=q('[name="dpi"]'),px=q('[name="pixels"]'),physical=q('[name="physical"]'),unit=q('[name="unit"]'),out=q('[data-result]'),swap=q('[data-swap]'),copy=q('[data-copy]');let copyText='';function calc(){const d=Math.max(1,parseFloat(dpi.value)||300);if(mode.value==='px-to-physical'){const p=Math.max(0,parseFloat(px.value)||0),inch=p/d,cm=inch*2.54,mm=cm*10;copyText=`${p} px at ${d} DPI = ${inch.toFixed(4)} in = ${cm.toFixed(3)} cm = ${mm.toFixed(2)} mm`;out.innerHTML=`<strong>${p.toLocaleString()} px</strong><span>${inch.toFixed(4)} inches</span><span>${cm.toFixed(3)} cm</span><span>${mm.toFixed(2)} mm</span>`;}else{const v=Math.max(0,parseFloat(physical.value)||0),u=unit.value,inch=u==='in'?v:u==='cm'?v/2.54:v/25.4,p=Math.round(inch*d);copyText=`${v} ${u} at ${d} DPI = ${p} px`;out.innerHTML=`<strong>${p.toLocaleString()} px</strong><span>${v} ${u} at ${d} DPI</span><span>${(inch*2.54).toFixed(3)} cm · ${(inch*25.4).toFixed(2)} mm · ${inch.toFixed(4)} in</span>`;}r.dataset.mode=mode.value;}[mode,dpi,px,physical,unit].forEach(e=>e&&e.addEventListener('input',calc));swap&&swap.addEventListener('click',()=>{mode.value=mode.value==='px-to-physical'?'physical-to-px':'px-to-physical';calc();});copy&&copy.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(copyText);const old=copy.textContent;copy.textContent='Copied';setTimeout(()=>copy.textContent=old,1200);}catch{}});calc();})();
